<?php

/*
 * Test that objects in tables whose IDs are generated by the database (e.g. SERIAL) get their ID
 * and default values back after being created or saved.
 */

use Programster\PgsqlObjects\CacheMode;

class TestDatabaseGeneratedId
{
    public function __construct()
    {
        $db = ConnectionHandler::getDb();
        $db->query("TRUNCATE {$db->escapeIdentifier("ticket")} RESTART IDENTITY");
        TicketTable::getInstance()->emptyCache();
    }


    public function run() : void
    {
        $this->testCreate();
        $this->testSave();
        $this->testGenerateIdThrows();
        $this->testClone();
    }


    private function testGenerateIdThrows() : void
    {
        $threw = false;

        try
        {
            TicketTable::getInstance()->generateId();
        }
        catch (\Programster\PgsqlObjects\Exceptions\ExceptionIdGeneratedInDatabase)
        {
            $threw = true;
        }

        if ($threw === false)
        {
            throw new \Exception("generateId() did not throw for a table whose IDs are generated by the database.");
        }
    }


    private function testClone() : void
    {
        $original = TicketTable::getInstance()->insert(['title' => 'original']);
        $clone = clone $original;

        if ($clone->getId() !== null)
        {
            throw new \Exception("A clone of a database-generated ID object should have no ID until it is saved.");
        }

        $clone->save();

        if ($clone->getId() === null || $clone->getId() === $original->getId())
        {
            throw new \Exception("Saving a clone did not give it its own database-generated ID.");
        }
    }


    private function testCreate() : void
    {
        $ticket1 = TicketTable::getInstance()->insert(['title' => 'first']);
        $ticket2 = TicketTable::getInstance()->insert(['title' => 'second']);

        if ($ticket1->getId() === null || $ticket2->getId() === null)
        {
            throw new \Exception("insert() returned an object without the database-generated ID.");
        }

        // SERIAL is an integer column, so its IDs should come back as PHP ints, however the object was made.
        $loadedFromDatabase = TicketTable::getInstance()->load($ticket1->getId(), CacheMode::UPDATE_CACHE);
        $loadedFromLoadAll = TicketTable::getInstance()->loadAll(CacheMode::UPDATE_CACHE)[0];

        $ticketsBySource = ['insert()' => $ticket1, 'load()' => $loadedFromDatabase, 'loadAll()' => $loadedFromLoadAll];

        foreach ($ticketsBySource as $source => $ticket)
        {
            if (!is_int($ticket->getId()))
            {
                $actual = var_export($ticket->getId(), true);
                throw new \Exception("The integer ID from {$source} was not a PHP int, got {$actual}.");
            }
        }

        if ($ticket1->getId() === $ticket2->getId())
        {
            throw new \Exception("insert() returned two objects with the same ID.");
        }

        if ($ticket1->getStatus() !== 'open')
        {
            throw new \Exception("insert() did not pick up the database default for status.");
        }

        if (TicketTable::getInstance()->load($ticket1->getId())->getTitle() !== 'first')
        {
            throw new \Exception("Loading the first ticket returned the wrong object.");
        }
    }


    private function testSave() : void
    {
        $ticket = TicketRecord::createNewFromArray(['title' => 'saved']);
        $ticket->save();

        if ($ticket->getId() === null)
        {
            throw new \Exception("save() did not set the database-generated ID on the object.");
        }

        // a second save must update the existing row, not silently update nothing.
        $ticket->update(['title' => 'renamed']);
        $reloaded = TicketTable::getInstance()->load($ticket->getId(), CacheMode::UPDATE_CACHE);

        if ($reloaded->getTitle() !== 'renamed')
        {
            throw new \Exception("Updating a saved ticket did not change the row in the database.");
        }
    }
}
